"use client";
import "./styles/skeuo-section-dock.css";

import type { ReactNode, KeyboardEvent } from "react";
export type DockItem = { value: string; label: string; icon: ReactNode };
/** Portfolio section dock, controlled so it also works inside panels and apps. */
export function SkeuoSectionDock({ items, value, onValueChange, orientation = "vertical", label = "Sections" }: { items: DockItem[]; value: string; onValueChange: (value: string) => void; orientation?: "vertical" | "horizontal"; label?: string }) {
  function navigate(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const previous = orientation === "vertical" ? "ArrowUp" : "ArrowLeft";
    const next = orientation === "vertical" ? "ArrowDown" : "ArrowRight";
    if (![previous, next, "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    const target = event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : (index + (event.key === next ? 1 : items.length - 1)) % items.length;
    onValueChange(items[target].value);
    event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>("button")[target]?.focus();
  }
  return <nav data-sk-root="" className="sk-section-dock" data-orientation={orientation} aria-label={label}><div className="sk-dock-track">{items.map((item,index) => <button type="button" key={item.value} className="sk-dock-key" aria-label={item.label} aria-current={value === item.value ? "page" : undefined} tabIndex={value === item.value ? 0 : -1} onClick={() => onValueChange(item.value)} onKeyDown={event => navigate(event,index)}>{item.icon}<span className="sk-dock-tooltip">{item.label}</span></button>)}</div></nav>;
}

@import "./skeuo-base.css";
.sk-section-dock{display:block;max-width:100%;padding:9px;border:1px solid var(--sk-key-edge);border-radius:29px;background:linear-gradient(145deg,var(--sk-surface-raised),var(--sk-surface));box-shadow:inset 0 2px 1px var(--sk-highlight),inset 1px 0 var(--sk-highlight),inset 0 -2px var(--sk-base),0 5px var(--sk-base),0 6px var(--sk-key-edge),0 12px 20px var(--sk-shadow);}
.sk-dock-track{display:flex;flex-direction:column;gap:12px;padding:9px 8px 12px;width:max-content;border:1px solid var(--sk-edge);border-radius:21px;background:var(--sk-base);box-shadow:inset 0 5px 9px var(--sk-shadow),inset 2px 0 5px var(--sk-shadow),inset -1px 0 3px var(--sk-shadow),0 1px var(--sk-highlight);}
.sk-section-dock[data-orientation="horizontal"]{overflow-x:auto;scrollbar-width:thin;}
.sk-section-dock[data-orientation="horizontal"] .sk-dock-track{flex-direction:row;}
.sk-dock-key{position:relative;display:grid;place-items:center;width:50px;height:50px;flex-shrink:0;padding:0;border:1px solid var(--sk-key-edge);border-radius:12px;color:var(--sk-muted);background:linear-gradient(145deg,var(--sk-key),var(--sk-surface));box-shadow:inset 0 2px var(--sk-highlight),inset 2px 0 2px var(--sk-highlight),inset 0 -3px var(--sk-base),0 3px var(--sk-base),0 4px var(--sk-key-edge),0 6px 4px #00000025;cursor:pointer;transition:transform .15s,color .2s;}
.sk-dock-key > svg{width:24px;height:24px;}
.sk-dock-key::before{content:"";position:absolute;inset:4px 4px 5px;border:1px solid color-mix(in srgb,var(--sk-key-edge) 45%,transparent);border-radius:8px;box-shadow:inset 0 2px 3px var(--sk-shadow),inset 0 -1px var(--sk-highlight);pointer-events:none;}
.sk-dock-key[aria-current="page"]{color:#fff;border-color:#1744bd;background:linear-gradient(145deg,#2457e6,#1d43b2);box-shadow:inset 0 2px #789aff,inset 2px 0 #ffffff25,inset 0 -3px #17399b,0 3px #17399b,0 4px #1744bd,0 6px 4px #00000030;}
.sk-dock-key[aria-current="page"]::before{border-color:#789aff80;box-shadow:inset 0 2px 3px #102a8b80,inset 0 -1px #789aff80;}
.sk-dock-key:active{transform:translateY(3px);box-shadow:inset 0 2px 4px var(--sk-shadow),0 1px var(--sk-key-edge);}
.sk-dock-key:focus-visible{outline:2px solid var(--sk-ring);outline-offset:4px;}
.sk-dock-tooltip{position:absolute;left:calc(100% + 16px);top:50%;transform:translateY(-50%);padding:7px 10px;border:1px solid var(--sk-edge);border-radius:5px;background:var(--sk-surface-raised);color:var(--sk-ink);box-shadow:0 3px 8px var(--sk-shadow);font-size:11px;white-space:nowrap;opacity:0;pointer-events:none;z-index:3;}
.sk-dock-key:is(:hover,:focus-visible) .sk-dock-tooltip{opacity:1;}
.sk-section-dock[data-orientation="horizontal"] .sk-dock-tooltip{top:auto;left:50%;bottom:calc(100% + 12px);transform:translateX(-50%);}
@media(prefers-reduced-motion:reduce){.sk-dock-key{transition:none;}}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
